from collections import defaultdict

def isCircle(N: int, A: List[str]) -> int:
    degree = defaultdict(int)
    graph = defaultdict(list)

    for s in A:
        degree[s[0]] += 1
        degree[s[-1]] -= 1
        graph[s[0]].append(s[-1])
        graph[s[-1]].append(s[0])

    odd_count = sum(1 for count in degree.values() if count % 2 != 0)

    if odd_count != 0:
        return 0

    visited = set()

    def dfs(node):
        stack = [node]
        while stack:
            current = stack.pop()
            if current not in visited:
                visited.add(current)
                for neighbor in graph[current]:
                    stack.append(neighbor)

    start_node = A[0][0]
    dfs(start_node)

    if len(visited) != len(graph):
        return 0

    return 1
